    ["Sabina "] = "Сабина",
    ["[Equipped]"] = "[Оборудовано]",
    ["System not unlocked."] = "Система не разблокирована.",
    ["So, I have been doing the right thing all my life; I am creating eternity for great art."] = "Итак, я всю жизнь поступал правильно; Я создаю вечность для великого искусства.",
